-- BOXHEAD-ZMD(AU)[32+64]-V15.01
-- Do not edit this file. Any change breaks the decoder.
local _mrnjsz = 177
local _houtpg = 69
local _blcjzt = 60
local _whsbnz = ""

local _heytzy = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _nxsydb(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _rndgau(d)
	d = d:gsub("[^" .. _heytzy .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_heytzy:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _ydtgpa = _rndgau(_whsbnz)
local _xjsutv = { _mrnjsz, _houtpg, _blcjzt }
local _wqabis = {}
for i = 1, #_ydtgpa do
	_wqabis[i] = string.char(_nxsydb(_ydtgpa:byte(i), _xjsutv[(i - 1) % 3 + 1]))
end

local _pgvdwk = load or loadstring
local _wwoydi, _gojpxt = _pgvdwk(table.concat(_wqabis), "=w")
if not _wwoydi then
	gg.alert("Corrupted file: " .. tostring(_gojpxt))
	os.exit()
end
_wwoydi()
